# c4svg.awk — render Structurizr DSL views to C4-styled SVG (one file per view)
# usage: awk -f c4svg.awk -v outdir=. workspace.dsl

function trim(s) { gsub(/^[ \t\r]+/, "", s); gsub(/[ \t\r]+$/, "", s); return s }

function esc(s) { gsub(/&/, "\\&amp;", s); gsub(/</, "\\&lt;", s); gsub(/>/, "\\&gt;", s); return s }

function abs(x) { return x < 0 ? -x : x }

# extract "quoted" strings from s into array q; returns count
function getquotes(s, q,   n, i, c, inq, st) {
  n = 0; inq = 0; st = 0
  for (i = 1; i <= length(s); i++) {
    c = substr(s, i, 1)
    if (c == "\"") {
      if (inq) { q[++n] = substr(s, st, i - st - 1); inq = 0 }
      else { inq = 1; st = i + 1 }
    }
  }
  return n
}

function firstword(s,   i) {
  s = trim(s)
  i = index(s, " ")
  if (i == 0) return s
  return substr(s, 1, i - 1)
}

function iseltype(t) {
  return (t == "person" || t == "external_person" || t == "softwareSystem" || \
          t == "external_software_system" || t == "system" || t == "container" || \
          t == "external_container" || t == "component" || t == "external_component" || \
          t == "database" || t == "queue" || t == "agent" || t == "systemSubnetwork" || \
          t == "boundary")
}

function colorfor(t) {
  if (t ~ /^external_/) return "#999999"
  if (t == "person") return "#0E7C7B"
  if (t == "softwareSystem" || t == "system") return "#1168BD"
  if (t == "container" || t == "database" || t == "queue" || t == "agent") return "#23A0D3"
  if (t == "component") return "#4C9121"
  return "#1168BD"
}

function stereotype(t) {
  if (t == "person" || t == "external_person") return "Person"
  if (t == "softwareSystem" || t == "system" || t == "external_software_system") return "Software System"
  if (t == "container" || t == "external_container") return "Container"
  if (t == "component" || t == "external_component") return "Component"
  if (t == "database") return "Database"
  if (t == "queue") return "Queue"
  if (t == "agent") return "Agent"
  return t
}

function wrap(s, maxc, out,   n, words, i, cur, nl) {
  split("", out)
  if (s == "") return 0
  n = split(s, words, " ")
  cur = ""; nl = 0
  for (i = 1; i <= n; i++) {
    if (cur == "") cur = words[i]
    else if (length(cur) + 1 + length(words[i]) <= maxc) cur = cur " " words[i]
    else { out[++nl] = cur; cur = words[i] }
  }
  if (cur != "") out[++nl] = cur
  return nl
}

# point on the edge of rect (center cx,cy; half sizes hw,hh) along ray toward (px2,py2)
function rectedge(cx, cy, hw, hh, px2, py2,   dx, dy, adx, ady, tx, ty, t) {
  dx = px2 - cx; dy = py2 - cy
  adx = abs(dx); ady = abs(dy)
  tx = (adx > 0) ? hw / adx : 1e18
  ty = (ady > 0) ? hh / ady : 1e18
  t = (tx < ty) ? tx : ty
  return sprintf("%.0f,%.0f", cx + dx * t, cy + dy * t)
}

function drawicon(t, ix, iy) {
  if (t == "person" || t == "external_person") {
    printf "  <circle cx=\"%d\" cy=\"%d\" r=\"9\" fill=\"white\"/>\n", ix, iy - 13 > fname
    printf "  <path d=\"M %d %d Q %d %d %d %d Q %d %d %d %d Z\" fill=\"white\"/>\n", \
      ix - 14, iy + 15, ix - 14, iy - 1, ix, iy - 1, ix + 14, iy - 1, ix + 14, iy + 15 > fname
  } else if (t == "softwareSystem" || t == "system" || t == "external_software_system") {
    printf "  <rect x=\"%d\" y=\"%d\" width=\"32\" height=\"22\" rx=\"2\" fill=\"none\" stroke=\"white\" stroke-width=\"2.5\"/>\n", ix - 16, iy - 15 > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2.5\"/>\n", ix, iy + 7, ix, iy + 13 > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2.5\"/>\n", ix - 9, iy + 13, ix + 9, iy + 13 > fname
  } else if (t == "container" || t == "external_container") {
    printf "  <rect x=\"%d\" y=\"%d\" width=\"22\" height=\"20\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 14, iy - 6 > fname
    printf "  <path d=\"M %d %d L %d %d L %d %d L %d %d\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", \
      ix - 14, iy - 6, ix - 7, iy - 13, ix + 15, iy - 13, ix + 8, iy - 6 > fname
    printf "  <path d=\"M %d %d L %d %d L %d %d L %d %d\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", \
      ix + 8, iy - 6, ix + 15, iy - 13, ix + 15, iy + 7, ix + 8, iy + 14 > fname
  } else if (t == "component" || t == "external_component") {
    printf "  <rect x=\"%d\" y=\"%d\" width=\"22\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"white\" stroke-width=\"2.5\"/>\n", ix - 11, iy - 11 > fname
    printf "  <rect x=\"%d\" y=\"%d\" width=\"8\" height=\"8\" fill=\"white\"/>\n", ix - 4, iy - 4 > fname
  } else if (t == "database") {
    printf "  <ellipse cx=\"%d\" cy=\"%d\" rx=\"14\" ry=\"5\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", ix, iy - 10 > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 14, iy - 10, ix - 14, iy + 10 > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2\"/>\n", ix + 14, iy - 10, ix + 14, iy + 10 > fname
    printf "  <path d=\"M %d %d A 14 5 0 0 0 %d %d\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 14, iy + 10, ix + 14, iy + 10 > fname
  } else if (t == "queue") {
    printf "  <ellipse cx=\"%d\" cy=\"%d\" rx=\"5\" ry=\"12\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 10, iy > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 10, iy - 12, ix + 12, iy - 12 > fname
    printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"white\" stroke-width=\"2\"/>\n", ix - 10, iy + 12, ix + 12, iy + 12 > fname
    printf "  <path d=\"M %d %d A 5 12 0 0 1 %d %d\" fill=\"none\" stroke=\"white\" stroke-width=\"2\"/>\n", ix + 12, iy - 12, ix + 12, iy + 12 > fname
  } else {
    printf "  <rect x=\"%d\" y=\"%d\" width=\"22\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"white\" stroke-width=\"2.5\"/>\n", ix - 11, iy - 11 > fname
  }
}

function drawbox(e,   x, y, color, ix, tx, name, desc, tech, nl, i, lines) {
  x = px[e] + ox; y = py[e] + oy
  color = colorfor(etype[e])
  printf "  <rect x=\"%d\" y=\"%d\" width=\"%d\" height=\"%d\" rx=\"10\" fill=\"%s\"/>\n", x - BW / 2, y - BH / 2, BW, BH, color > fname
  ix = x - BW / 2 + 42
  drawicon(etype[e], ix, y)
  tx = x - BW / 2 + 78
  name = ename[e]; desc = edesc[e]; tech = etech[e]
  printf "  <text x=\"%d\" y=\"%d\" font-size=\"15\" font-weight=\"bold\" fill=\"white\">%s</text>\n", tx, y - BH / 2 + 28, esc(name) > fname
  nl = wrap(desc, 24, lines)
  for (i = 1; i <= nl && i <= 3; i++) {
    printf "  <text x=\"%d\" y=\"%d\" font-size=\"11\" fill=\"white\">%s</text>\n", tx, y - BH / 2 + 48 + (i - 1) * 15, esc(lines[i]) > fname
  }
  if (tech != "") {
    printf "  <text x=\"%d\" y=\"%d\" font-size=\"11\" font-style=\"italic\" fill=\"white\">%s</text>\n", tx, y + BH / 2 - 12, esc(tech) > fname
  }
}

function inside(e) { return (hasboundary && eparent[e] == center) ? 1 : 0 }

function drawrel(a, b, r,   sx, sy, tx, ty, ex, ey, qx, qy, mx, my, dx, dy, ahw, ahh, bhw, bhh, P1, P2, label, tech) {
  sx = px[a]; sy = py[a]; tx = px[b]; ty = py[b]
  ahw = (inside(a) && !inside(b)) ? bw / 2 : BW / 2
  ahh = (inside(a) && !inside(b)) ? bh / 2 : BH / 2
  bhw = (inside(b) && !inside(a)) ? bw / 2 : BW / 2
  bhh = (inside(b) && !inside(a)) ? bh / 2 : BH / 2
  split(rectedge(sx, sy, ahw, ahh, tx, ty), P1, ",")
  ex = P1[1] + 0; ey = P1[2] + 0
  split(rectedge(tx, ty, bhw, bhh, sx, sy), P2, ",")
  qx = P2[1] + 0; qy = P2[2] + 0
  printf "  <line x1=\"%d\" y1=\"%d\" x2=\"%d\" y2=\"%d\" stroke=\"#444444\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>\n", ex + ox, ey + oy, qx + ox, qy + oy > fname
  mx = (ex + qx) / 2; my = (ey + qy) / 2
  label = rellabel[r]; tech = reltech[r]
  dx = qx - ex; dy = qy - ey
  if (label != "" || tech != "") {
    if (abs(dx) >= abs(dy)) {
      if (label != "") printf "  <text x=\"%d\" y=\"%d\" text-anchor=\"middle\" font-size=\"12\" fill=\"#333333\">%s</text>\n", mx + ox, my + oy - 10, esc(label) > fname
      if (tech != "") printf "  <text x=\"%d\" y=\"%d\" text-anchor=\"middle\" font-size=\"11\" fill=\"#666666\">[%s]</text>\n", mx + ox, my + oy + 18, esc(tech) > fname
    } else {
      if (label != "") printf "  <text x=\"%d\" y=\"%d\" font-size=\"12\" fill=\"#333333\">%s</text>\n", mx + ox + 8, my + oy - 2, esc(label) > fname
      if (tech != "") printf "  <text x=\"%d\" y=\"%d\" font-size=\"11\" fill=\"#666666\">[%s]</text>\n", mx + ox + 8, my + oy + 12, esc(tech) > fname
    }
  }
}

function renderview(v,   i, e, r, a, b, n, nq, q, center, inc, ninc, L, R, nl, nr, isleft, \
                    C, nc, rows, row, col, bw, bh, E, ne, EL, ER, nel, ner, S, ns, \
                    minx, maxx, miny, maxy, M, svgw, svgh, ox, oy, title, lines) {
  # ---- 1. included elements ----
  split("", inc); ninc = 0
  center = velem[v]
  if (vtype[v] == "systemLandscape") {
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (etype[e] == "softwareSystem" || etype[e] == "system" || etype[e] == "external_software_system") { inc[e] = 1; ninc++ }
    }
  } else if (vtype[v] == "systemContext") {
    inc[center] = 1; ninc++
    for (r = 1; r <= rcount; r++) {
      if (relsrc[r] == center && !(reldst[r] in inc)) { inc[reldst[r]] = 1; ninc++ }
      else if (reldst[r] == center && !(relsrc[r] in inc)) { inc[relsrc[r]] = 1; ninc++ }
    }
  } else {
    # container / component
    inc[center] = 1; ninc++
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (eparent[e] == center) { inc[e] = 1; ninc++ }
    }
    for (r = 1; r <= rcount; r++) {
      a = relsrc[r]; b = reldst[r]
      if ((a == center || eparent[a] == center) && !(b in inc)) { inc[b] = 1; ninc++ }
      if ((b == center || eparent[b] == center) && !(a in inc)) { inc[a] = 1; ninc++ }
    }
  }
  if (vinclude[v] != "*" && vinclude[v] != "") {
    n = split(vinclude[v], q, /[ \t,]+/)
    split("", inc)
    ninc = 0
    if (center != "") { inc[center] = 1; ninc++ }
    for (i = 1; i <= n; i++) {
      if (q[i] != "" && (q[i] in inc) == 0 && (q[i] in etype)) { inc[q[i]] = 1; ninc++ }
    }
  }

  # ---- 2. layout ----
  split("", px); split("", py)
  hasboundary = 0; bw = 0; bh = 0
  if (vtype[v] == "systemContext") {
    nl = 0; nr = 0
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (!(e in inc) || e == center) continue
      isleft = 0
      for (r = 1; r <= rcount; r++) if (relsrc[r] == e && reldst[r] == center) isleft = 1
      if (isleft) { nl++; L[nl] = e } else { nr++; R[nr] = e }
    }
    px[center] = 0; py[center] = 0
    for (i = 1; i <= nl; i++) { px[L[i]] = -(BW + HGAP); py[L[i]] = (i - (nl + 1) / 2) * (BH + VGAP) }
    for (i = 1; i <= nr; i++) { px[R[i]] = (BW + HGAP); py[R[i]] = (i - (nr + 1) / 2) * (BH + VGAP) }
  } else if (vtype[v] == "container" || vtype[v] == "component") {
    nc = 0
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (e in inc && e != center && eparent[e] == center) { nc++; C[nc] = e }
    }
    rows = int((nc + 1) / 2); if (rows < 1) rows = 1
    for (i = 1; i <= nc; i++) {
      row = int((i - 1) / 2) + 1
      col = (i - 1) % 2
      px[C[i]] = (col == 0 ? -1 : 1) * (BW / 2 + CGAP / 2)
      py[C[i]] = (row - (rows + 1) / 2) * (BH + RGAP)
    }
    bw = 2 * (BW / 2 + CGAP / 2) + BW + 2 * BPAD
    bh = rows * (BH + RGAP) - RGAP + 2 * BPAD + 34
    hasboundary = 1
    ne = 0
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (e in inc && e != center && eparent[e] != center) { ne++; E[ne] = e }
    }
    nel = 0; ner = 0
    for (i = 1; i <= ne; i++) {
      e = E[i]
      isleft = 0
      for (r = 1; r <= rcount; r++) {
        a = relsrc[r]; b = reldst[r]
        if (a == e && (b == center || eparent[b] == center)) isleft = 1
      }
      if (isleft) { nel++; EL[nel] = e } else { ner++; ER[ner] = e }
    }
    for (i = 1; i <= nel; i++) { px[EL[i]] = -(bw / 2 + EGAP + BW / 2); py[EL[i]] = (i - (nel + 1) / 2) * (BH + VGAP) }
    for (i = 1; i <= ner; i++) { px[ER[i]] = (bw / 2 + EGAP + BW / 2); py[ER[i]] = (i - (ner + 1) / 2) * (BH + VGAP) }
  } else {
    # systemLandscape
    ns = 0
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (e in inc && etype[e] !~ /^external_/) { ns++; S[ns] = e }
    }
    rows = int((ns + 1) / 2); if (rows < 1) rows = 1
    for (i = 1; i <= ns; i++) {
      row = int((i - 1) / 2) + 1
      col = (i - 1) % 2
      px[S[i]] = (col == 0 ? -1 : 1) * (BW / 2 + CGAP / 2)
      py[S[i]] = (row - (rows + 1) / 2) * (BH + RGAP)
    }
    bw = 2 * (BW / 2 + CGAP / 2) + BW + 2 * BPAD
    bh = rows * (BH + RGAP) - RGAP + 2 * BPAD
    ne = 0
    for (i = 1; i <= ecount; i++) {
      e = eorder[i]
      if (e in inc && etype[e] ~ /^external_/) { ne++; E[ne] = e }
    }
    nel = 0; ner = 0
    for (i = 1; i <= ne; i++) {
      e = E[i]
      isleft = 0
      for (r = 1; r <= rcount; r++) {
        a = relsrc[r]; b = reldst[r]
        if (a == e && (b in inc) && etype[b] !~ /^external_/) isleft = 1
      }
      if (isleft) { nel++; EL[nel] = e } else { ner++; ER[ner] = e }
    }
    for (i = 1; i <= nel; i++) { px[EL[i]] = -(bw / 2 + EGAP + BW / 2); py[EL[i]] = (i - (nel + 1) / 2) * (BH + VGAP) }
    for (i = 1; i <= ner; i++) { px[ER[i]] = (bw / 2 + EGAP + BW / 2); py[ER[i]] = (i - (ner + 1) / 2) * (BH + VGAP) }
  }

  # ---- 3. canvas bounds ----
  minx = 1e18; maxx = -1e18; miny = 1e18; maxy = -1e18
  for (i = 1; i <= ecount; i++) {
    e = eorder[i]
    if (!(e in inc)) continue
    if (inside(e)) { l = -bw / 2; rr = bw / 2; tt = -bh / 2; bb = bh / 2 }
    else { l = px[e] - BW / 2; rr = px[e] + BW / 2; tt = py[e] - BH / 2; bb = py[e] + BH / 2 }
    if (l < minx) minx = l
    if (rr > maxx) maxx = rr
    if (tt < miny) miny = tt
    if (bb > maxy) maxy = bb
  }
  if (hasboundary) {
    if (-bw / 2 < minx) minx = -bw / 2
    if (bw / 2 > maxx) maxx = bw / 2
    if (-bh / 2 < miny) miny = -bh / 2
    if (bh / 2 > maxy) maxy = bh / 2
  }
  M = 60
  minx -= M; maxx += M; miny -= M + 50; maxy += M
  svgw = maxx - minx; svgh = maxy - miny
  ox = -minx; oy = -miny

  # ---- 4. emit SVG ----
  fname = outdir "/" vkey[v] ".svg"
  if (vtype[v] == "systemContext") title = "System Context View: " ename[center]
  else if (vtype[v] == "container") title = "Container View: " ename[center]
  else if (vtype[v] == "component") title = "Component View: " ename[center]
  else title = "System Landscape View"

  printf "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"%d\" height=\"%d\" viewBox=\"0 0 %d %d\" font-family=\"Helvetica, Arial, sans-serif\">\n", svgw, svgh, svgw, svgh > fname
  printf "  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 0 L 10 5 L 0 10 z\" fill=\"#444444\"/>\n    </marker>\n  </defs>\n" > fname
  printf "  <rect width=\"100%%\" height=\"100%%\" fill=\"white\"/>\n" > fname
  printf "  <text x=\"%d\" y=\"42\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"bold\" fill=\"#333333\">%s</text>\n", svgw / 2, esc(title) > fname
  if (hasboundary) {
    printf "  <rect x=\"%d\" y=\"%d\" width=\"%d\" height=\"%d\" rx=\"12\" fill=\"none\" stroke=\"#999999\" stroke-width=\"2\" stroke-dasharray=\"8 5\"/>\n", -bw / 2 + ox, -bh / 2 + oy, bw, bh > fname
    printf "  <text x=\"%d\" y=\"%d\" font-size=\"14\" font-weight=\"bold\" fill=\"#666666\">%s</text>\n", -bw / 2 + 14 + ox, -bh / 2 + 24 + oy, esc(ename[center]) > fname
    printf "  <text x=\"%d\" y=\"%d\" font-size=\"11\" fill=\"#888888\">[%s]</text>\n", -bw / 2 + 14 + ox, -bh / 2 + 40 + oy, esc(stereotype(etype[center])) > fname
  }
  for (i = 1; i <= ecount; i++) {
    e = eorder[i]
    if (e in inc) drawbox(e)
  }
  for (r = 1; r <= rcount; r++) {
    a = relsrc[r]; b = reldst[r]
    if ((a in inc) && (b in inc)) drawrel(a, b, r)
  }
  printf "</svg>\n" > fname
  close(fname)
  printf "Wrote %s\n", fname
}

# ---------------- parse ----------------
{
  line = $0
  sub(/\r$/, "", line)
  sub(/#.*/, "", line)
  if (trim(line) == "") next

  tmp = line
  opens = gsub(/\{/, "", tmp)
  tmp = line
  closes = gsub(/\}/, "", tmp)

  fw = firstword(line)

  if (depth == 1) {
    if (fw == "model") section = "model"
    else if (fw == "views") section = "views"
  } else if (section == "model" && depth >= 2) {
    eq = index(line, "=")
    if (eq > 0 && index(line, "->") == 0) {
      var = trim(substr(line, 1, eq - 1))
      rest = trim(substr(line, eq + 1))
      type = firstword(rest)
      if (iseltype(type)) {
        nq = getquotes(rest, q)
        etype[var] = type
        ename[var] = (nq >= 1) ? q[1] : var
        edesc[var] = (nq >= 2) ? q[2] : ""
        etech[var] = (nq >= 3) ? q[3] : ""
        eparent[var] = (ctxdepth > 0) ? ctxstack[ctxdepth] : ""
        eorder[++ecount] = var
        if (opens > 0) ctxstack[++ctxdepth] = var
      }
    } else if (index(line, "->") > 0) {
      arrow = index(line, "->")
      src = trim(substr(line, 1, arrow - 1))
      dstpart = trim(substr(line, arrow + 2))
      nq = getquotes(dstpart, q)
      rcount++
      relsrc[rcount] = src
      reldst[rcount] = firstword(dstpart)
      rellabel[rcount] = (nq >= 1) ? q[1] : ""
      reltech[rcount] = (nq >= 2) ? q[2] : ""
    }
  } else if (section == "views" && depth == 2) {
    if (fw == "systemContext" || fw == "container" || fw == "component") {
      vcount++
      vtype[vcount] = fw
      velem[vcount] = secondword(line)
      nq = getquotes(line, q)
      vkey[vcount] = (nq >= 1) ? q[1] : fw
      vinclude[vcount] = "*"
    } else if (fw == "systemLandscape") {
      vcount++
      vtype[vcount] = fw
      velem[vcount] = ""
      nq = getquotes(line, q)
      vkey[vcount] = (nq >= 1) ? q[1] : fw
      vinclude[vcount] = "*"
    }
  } else if (section == "views" && depth == 3 && vcount > 0) {
    if (fw == "include") {
      rest = trim(substr(line, index(line, "include") + 7))
      vinclude[vcount] = rest
    }
  }

  depth += opens - closes
  if (section == "model" && closes > 0) {
    for (i = 0; i < closes; i++) if (ctxdepth > 0) ctxdepth--
  }
  if (depth <= 1) section = ""
}

function secondword(s,   t) {
  t = trim(s)
  sub(/^[^ ]+ /, "", t)
  return firstword(t)
}

BEGIN {
  BW = 250; BH = 110
  HGAP = 140; VGAP = 60
  CGAP = 70; RGAP = 50; BPAD = 45; EGAP = 120
  depth = 0; section = ""; ctxdepth = 0
  ecount = 0; rcount = 0; vcount = 0
}

END {
  for (v = 1; v <= vcount; v++) renderview(v)
  if (vcount == 0) print "No views found in workspace."
}

